_SERIALIZE(_airbyte_data), \'Report_Type\') Report_type FROM ( SELECT *, MAX(_airbyte_emitted_at) OVER ( PARTITION BY (_airbyte_emitted_at::date )) AS MAX_TIME_OF_THE_DAY FROM public._airbyte_raw_blinkit_anveshan_ads ) WHERE _airbyte_emitted_at >= (MAX_TIME_OF_THE_DAY - INTERVAL \'10 MINUTES\') ; DROP TABLE IF EXISTS public.anveshan_Blinkit_ads_Fact_items; CREATE TABLE public.anveshan_Blinkit_ads_Fact_items AS WITH blinkit_ads AS ( SELECT COALESCE( TO_DATE(TRIM(ba.date), \'DD-MM-YYYY\'), TO_DATE(TRIM(ba.date), \'YYYY-MM-DD\'), TO_DATE(TRIM(ba.date), \'DD/MM/YYYY\') ) AS Date, TRY_CAST(TRIM(REGEXP_REPLACE(ba.estimated_budget_consumed, \'[^0-9.]\')) AS DOUBLE PRECISION) AS Estimated_Budget_Consumed, TRY_CAST(TRIM(REGEXP_REPLACE(ba.total_roas, \'[^0-9.]\')) AS DOUBLE PRECISION) AS Total_RoAS, TRY_CAST(TRIM(REGEXP_REPLACE(ba.cpm, \'[^0-9.]\')) AS DOUBLE PRECISION) AS CPM, TRY_CAST(TRIM(REGEXP_REPLACE(ba.direct_atc, \'[^0-9.]\')) AS DOUBLE PRECISION) AS Direct_ATC, TRY_CAST(TRIM(REGEXP_REPLACE(ba.direct_quantities_sold, \'[^0-9.]\')) AS NUMERIC) AS Direct_Quantities_Sold, TRY_CAST(TRIM(REGEXP_REPLACE(ba.direct_sales, \'[^0-9.]\')) AS DOUBLE PRECISION) AS Direct_Sales, TRY_CAST(TRIM(REGEXP_REPLACE(ba.impressions, \'[^0-9.]\')) AS NUMERIC) AS Impressions, ba.campaign_name as campaign_name, NULL AS collection, TRY_CAST(TRIM(REGEXP_REPLACE(ba.match_type, \'[^0-9.]\')) AS DOUBLE PRECISION) AS CTR, NULL::NUMERIC AS Reach, ba.targeting_type AS Match_Type, TRY_CAST(TRIM(REGEXP_REPLACE(ba.indirect_atc, \'[^0-9.]\')) AS NUMERIC) AS Unique_Clicks, ba.targeting_type AS Targeting_Type, ba.targeting_value AS Targeting_Value, report_type FROM public.blinkit_raw_anveshan_data ba ) SELECT Date, Estimated_Budget_Consumed, Total_RoAS, CPM, Direct_ATC, Direct_Quantities_Sold, Direct_Sales, Impressions, b.campaign_name, collection, CTR, Reach, Match_Type, Unique_Clicks AS clicks, Targeting_Type, Targeting_Value, Report_type, gb.category, gb.type_of_ads, gb.pnl_category FROM blinkit_ads left join (select * from (select \"campaign name\" as campaign_name, \"sub-category\" as category, \"type of ad\" as type_of_ads, \"pnl category\" pnl_category, row_number() over (partition by \"campaign name\" order by \"sub-category\" desc) as rw from public.GS_blinkit_Campaign_Mapping ) where rw=1 ) gb ON upper(trim(gb.campaign_name)) = upper(b.campaign_name);",
